        return send(res, 403, { ok: false, error: 'PRIVATE_CONTROL_AUTH_REQUIRED' });
      if (closing) return send(res, 503, { ok: false, error: 'OPERATOR_CLOSING' });
      if (req.method !== 'POST' || req.url !== '/v1/command') {
