/* MIT. Neutral, compact workspace controls within the original Atlas. */
#saved-workspace{margin:0 0 34px;scroll-margin-top:20px}
.aw-toolbar{display:grid;grid-template-columns:minmax(180px,280px) minmax(0,1fr);gap:16px;align-items:end;padding:16px 0;border-top:1px solid var(--line);border-bottom:1px solid var(--line)}
.aw-buttons{display:flex;gap:8px;flex-wrap:wrap;align-items:center}
.aw-toolbar button{font-size:12px;padding:9px 12px}
.aw-summary{font-size:12px;color:var(--muted);padding:4px 0}
.aw-tabs{display:flex;gap:0;border-bottom:1px solid var(--line);margin:18px 0}
.aw-tabs button{color:var(--muted);background:transparent;border:0;border-bottom:2px solid transparent;padding:12px 18px;font-size:13px}
.aw-tabs button[aria-selected="true"]{color:var(--strong);border-bottom-color:var(--strong);background:#232323}
.aw-table-scroll{max-width:100%;overflow:auto;border:1px solid var(--line);scrollbar-color:#666 #202020}
.aw-table{width:100%;border-collapse:collapse;font-size:12px;line-height:1.5;text-align:left}
.aw-table th,.aw-table td{padding:11px 12px;vertical-align:top;border-bottom:1px solid var(--line);min-width:74px}
.aw-table thead th{font-size:10px;text-transform:uppercase;letter-spacing:.06em;font-weight:600;color:var(--muted);background:#202020;white-space:nowrap}
.aw-table tr:last-child td,.aw-table tr:last-child th{border-bottom:0}
.aw-table td:first-child{max-width:260px}.aw-table td:nth-child(2){max-width:360px}
