      return { captureId, file, sha256: expected.sha256, status: 'RECEIVED' };
    }); },
    finishCapture({ captureId }) { return mutate(async () => {
      const current = await state(), item = await entry(captureId, current);
      if (item.status === 'READY') return { ...item, captureId, pages: item.files.length };
      need(item.kind === 'NATIVE_CAPTURE' && item.files.length > 0, 'ATLAS_CAPTURE_HAS_NO_PAGES');
      const sessionBytes = await read(`captures/${captureId}/source-session.json`, PAGE_BYTES);
      const manifestBytes = await read(`captures/${captureId}/source-manifest.json`, MANIFEST_BYTES);
      need(hash(sessionBytes) === item.sessionSha256 && hash(manifestBytes) === item.manifestSha256, 'ATLAS_CAPTURE_SOURCE_CHANGED');
      const { session, manifest } = captureInputs(sessionBytes.toString('utf8'), manifestBytes.toString('utf8'));
      for (const file of item.files) await sourcePage(item, file.file);
      // The native engine checks query identity, pagination, chain and original
      // page hashes. Its request seam cannot acquire any additional page here.
      const nativeManifest = `captures/${captureId}/native/manifest.json`;
      if (!await read(nativeManifest, MANIFEST_BYTES, true)) await write(nativeManifest, manifestBytes, true);
      const result = await acquireCatalog({ captureDir: path(`captures/${captureId}/native`), request: session.request,
        allPages: session.allPages, maxPages: item.files.length, proxy: null },
      async () => { throw new InputError('ATLAS_IMPORT_CANNOT_FETCH_SOURCE'); });
      need(result.pages === item.files.length && result.observedRows === item.rows, 'ATLAS_CAPTURE_IMPORT_MISMATCH');
      item.status = 'READY'; item.nativeStatus = result.status; item.reportedTotal = manifest.total;
      item.updatedAt = now(); await saveState(current);
      return { ...item, captureId, pages: item.files.length };
    }); },
    receivePage({ name, pageText }) { return mutate(async () => {
      name = label(name);
      const bytes = textBytes(pageText, PAGE_BYTES, 'ATLAS_PAGE_TOO_LARGE'), value = decode(bytes), rows = rowsOf(value);
      const digest = hash(bytes), id = `page-${digest.slice(0, 40)}`, current = await state();
      if (!current.captures[id]) {
        await ensureDir(`captures/${id}/native`);
        await write(`captures/${id}/native/page-000000.json`, bytes, true);
        current.captures[id] = { id, captureId: id, name, kind: 'SINGLE_PAGE', status: 'READY', nativeStatus: 'SINGLE_PAGE',
          source: value.source ?? value.sourceUrl ?? null, rows: rows.length, reportedTotal: value.pagination?.total ?? null,
          observedAt: value.observedAt ?? value.capture?.capturedAt ?? null, receivedAt: now(), updatedAt: now(),
          files: [{ file: 'page-000000.json', sha256: digest, rows: rows.length, offset: value.pagination?.offset ?? null }] };
        await saveState(current);
      }
      return { ...current.captures[id], captureId: id, pages: 1 };
    }); },
    async capture({ captureId, query = '', page = 0, pageSize = 50 }) {
      need(!closed, 'ATLAS_WORKSPACE_CLOSED'); await queue;
      need(typeof query === 'string' && query.length <= 512 && Number.isSafeInteger(page) && page >= 0 &&
        Number.isSafeInteger(pageSize) && pageSize >= 1 && pageSize <= 200, 'ATLAS_QUERY_INVALID');
      const item = await entry(captureId), matches = [], start = page * pageSize;
      need(Number.isSafeInteger(start), 'ATLAS_QUERY_INVALID');
      let total = 0;
      const tokens = query.toLocaleLowerCase().split(/\s+/).filter(Boolean);
      for (const file of item.files) {
        const saved = await read(`captures/${captureId}/native/${file.file}`, PAGE_BYTES, true);
        if (!saved && item.status === 'RECEIVING') continue;
        need(saved && hash(saved) === file.sha256, 'ATLAS_SOURCE_PAGE_CHANGED');
        for (const [row, listing] of rowsOf(decode(saved)).entries()) {
          const searchable = JSON.stringify(listing).toLocaleLowerCase();
          if (!tokens.every(token => searchable.includes(token))) continue;
          if (total >= start && matches.length < pageSize) matches.push({ pageFile: file.file, row, listing });
          total++;
        }
      }
      return { capture: { ...item, pages: item.files.length }, offers: matches,
        pagination: { page, pageSize, total, nextPage: start + matches.length < total ? page + 1 : null } };
    },
    saveSelection(input) { return mutate(async () => {
      const current = await state(), item = await entry(input.captureId, current);
      const page = await sourcePage(item, input.pageFile);
      need(Number.isSafeInteger(input.row) && input.row >= 0 && Number.isSafeInteger(input.accept) && input.accept >= 0 &&
        plain(page.rows[input.row]?.accepts?.[input.accept]), 'ATLAS_EXPLICIT_OFFER_REQUIRED');
      const name = label(input.label), binding = { captureId: item.id, pageFile: input.pageFile, row: input.row, accept: input.accept, label: name };
      const id = input.selectionId ?? `selection-${identity(binding).slice(0, 36)}`;
      need(idOK(id), 'ATLAS_SELECTION_ID_INVALID');
      if (current.selections[id]) {
        const existing = await record(id, current);
        need(identity(Object.fromEntries(Object.keys(binding).map(key => [key, existing[key]]))) === identity(binding), 'ATLAS_SELECTION_ID_CONFLICT');
        return selectionView(existing);
      }
      const root = `selections/${id}/versions/000000`; await ensureDir(root);
      const old = await read(`${root}/record.json`, MANIFEST_BYTES, true);
      const listing = page.rows[input.row], resource = typeof listing.resource === 'string' ? listing.resource : listing.resource?.url;
      const value = old ? decode(old) : { id, ...binding, resource, revision: 0, stage: 'SELECTED',
        updatedAt: now(), request: null, inputs: { body: null, ticket: null }, prepared: null, handoff: null };
      need(identity(Object.fromEntries(Object.keys(binding).map(key => [key, value[key]]))) === identity(binding), 'ATLAS_SELECTION_ID_CONFLICT');
      return commit(current, root, value);
    }); },
    async selection({ selectionId }) { need(!closed, 'ATLAS_WORKSPACE_CLOSED'); await queue; return selectionView(await record(selectionId)); },
    prepareSelection(input) { return mutate(async () => {
      need(plain(input.request) && Object.keys(input.request).every(key =>
        ['intentId', 'url', 'method', 'headers', 'responseOut', 'ticketHeader'].includes(key)), 'ATLAS_EXPLICIT_REQUEST_REQUIRED');
      need(Number.isSafeInteger(input.revision) && input.revision >= 0, 'ATLAS_SELECTION_REVISION_REQUIRED');
      for (const key of ['bodyText', 'ticketText']) need(input[key] === undefined || input[key] === null || typeof input[key] === 'string', 'ATLAS_REQUEST_INPUT_INVALID');
      const current = await state(), prior = await record(input.selectionId, current), stage = await version(current, prior, 'prepare', input);
      if (stage.replay) return selectionView(stage.replay);
      const { root, value } = stage;
      value.request = copy(input.request); value.inputs = { body: null, ticket: null }; value.handoff = null;
      for (const [kind, field, limit, name] of [['body', 'bodyText', MAX_REQUEST_BODY_BYTES, 'request.body'], ['ticket', 'ticketText', 16384, 'operation-ticket.json']]) {
        const bytes = input[field] === undefined ? await inputBytes(prior.inputs?.[kind], limit)
          : input[field] === null ? null : textBytes(input[field], limit, 'ATLAS_REQUEST_INPUT_TOO_LARGE');
        if (bytes !== null) {
          const rel = `${root}/${name}`; await write(rel, bytes, true);
          value.inputs[kind] = { path: rel, bytes: bytes.length, sha256: hash(bytes) };
        }
      }
      if (!value.inputs.ticket) delete value.request.ticketHeader;
      const native = await prepared(value);
      if (native.ticket) parseOperationTicketBytes(native.ticket, native.draft.operation, { requireCurrent: true });
      const rel = `${root}/review.json`; await write(rel, native.data, true);
      value.prepared = { path: rel, bytes: native.data.length, sha256: native.configSha256 };
      value.stage = 'PREPARED';
      return commit(current, root, value);
    }); },
    createHandoff(input) { return mutate(async () => {
      need(Number.isSafeInteger(input.revision) && input.revision >= 0, 'ATLAS_SELECTION_REVISION_REQUIRED');
      const current = await state(), prior = await record(input.selectionId, current);
      need(prior.request, 'ATLAS_PREPARED_REQUEST_REQUIRED');
      const stage = await version(current, prior, 'handoff', input);
      if (stage.replay) return selectionView(stage.replay);
      const { root, value } = stage, native = await prepared(prior);
      const handoff = createOperationHandoff({ draft: native.draft, discoveryBytes: native.discovery,
        bodyBytes: native.body, ticketBytes: native.ticket, directory: path(root) });
      const bytes = json(handoff), rel = `${root}/handoff.json`;
      await write(rel, bytes, true);
      value.handoff = { path: rel, bytes: bytes.length, sha256: hash(bytes), acceptIndex: prior.accept,
        intentId: native.draft.operation.intentId };
      value.stage = 'HANDOFF'; return commit(current, root, value);
    }); },
    async *snapshotFiles() {
      need(!closed, 'ATLAS_WORKSPACE_CLOSED'); await queue;
      const snapshot = await read('workspace.json'), current = decode(snapshot);
      const roots = [...Object.keys(current.captures).map(id => `captures/${id}`), ...Object.keys(current.selections).map(id => `selections/${id}`)];
      const visit = async function* (rel) {
        for (const child of (await readdir(path(rel), { withFileTypes: true })).sort((a, b) => a.name.localeCompare(b.name))) {
          if (child.name.startsWith('.')) continue;
          need(!child.isSymbolicLink(), 'ATLAS_SNAPSHOT_SYMLINK_REFUSED');
          const selected = `${rel}/${child.name}`;
          if (child.isDirectory()) yield* visit(selected);
          else { need(child.isFile(), 'ATLAS_SNAPSHOT_FILE_INVALID'); yield { path: selected, bytes: await read(selected, Math.max(MANIFEST_BYTES, 4 * Math.ceil(MAX_REQUEST_BODY_BYTES / 3) + 2 * PAGE_BYTES)) }; }
        }
      };
      for (const root of roots) yield* visit(root);
      need((await read('workspace.json')).equals(snapshot), 'ATLAS_SNAPSHOT_CHANGED_RETRY');
      yield { path: 'workspace.json', bytes: snapshot };
    },
    async close() { if (!closed) { closed = true; await queue; await release(); } },
  };
  return api;
}

#!/usr/bin/env node
import { readFile, lstat, mkdir, writeFile } from 'node:fs/promises';
import { createHash } from 'node:crypto';
import { dirname, resolve } from 'node:path';
import { pathToFileURL } from 'node:url';
import { importOpenApi } from './importer.mjs';
import { parseOpenApiSource } from './source-document.mjs';
const sha = data => createHash('sha256').update(data).digest('hex');

export async function run(args = process.argv.slice(2), {report = true} = {}) {
  if (args[0] === 'har') return (await import('./har/cli.mjs')).runHarCLI(args.slice(1));
  if (args[0] === 'postman') return (await import('./postman/cli.mjs')).runPostmanCLI(args.slice(1));
  if (args[0] === 'weather') return (await import('./openweather/cli.mjs')).main(args.slice(1));
  if (args[0] === 'refresh') return (await import('./refresh-cli.mjs')).run(args.slice(1));
  if (args[0] === 'source')
    return (await import('./source-bundle-cli.mjs')).runSourceBundleCLI(args.slice(1));
  const options = new Map();
  for (let i = 0; i < args.length; i += 2) {
    if (!['--spec', '--config', '--out', '--service-bindings', '--upstream-bindings'].includes(args[i]) || !args[i + 1] || args[i + 1].startsWith('--') || options.has(args[i]))
      throw new Error('Usage: node cli.mjs --spec openapi.json --config selections.json --out NEW_DIRECTORY [--service-bindings bindings.json] [--upstream-bindings upstreams.json]');
    options.set(args[i], args[i + 1]);
  }
  if (!['--spec', '--config', '--out'].every(key => options.has(key))) throw new Error('Supply --spec, --config and --out');
  if (options.has('--upstream-bindings') && !options.has('--service-bindings'))
    throw new Error('--upstream-bindings requires --service-bindings');
  const input = async name => {
    const path = options.get(name), stat = await lstat(path);
    if (!stat.isFile() || stat.size > 4 * 1024 * 1024) throw new Error(name + ' requires a regular source file up to 4 MiB');
    const bytes = await readFile(path);
    if (bytes.length > 4 * 1024 * 1024) throw new Error('Input grew beyond size limit');
    const text=new TextDecoder('utf-8',{fatal:true,ignoreBOM:name==='--spec'}).decode(bytes);
    return { bytes, value:name==='--spec'?parseOpenApiSource(text).document:JSON.parse(text) };
  };
  const spec = await input('--spec'), config = await input('--config');
  const compiled = importOpenApi(spec.value, config.value);
  const bytes = Buffer.from(JSON.stringify(compiled, null, 2) + '\n');
  const bindings = options.has('--service-bindings') ? await input('--service-bindings') : null;
  // Metadata-only import need not load a network resource-server module.
  const createSellerServiceConfig = bindings
    ? (await import('./service-config.mjs')).createSellerServiceConfig : null;
  const serviceConfig = bindings ? createSellerServiceConfig(compiled, bindings.value) : null;
  const upstreamInput = options.has('--upstream-bindings') ? await input('--upstream-bindings') : null;
  let upstreamBytes = null;
  if (upstreamInput) {
    const { createContractUpstreamBindings } = await import('./response-contracts.mjs');
    const upstreams = createContractUpstreamBindings(spec.value, compiled, bindings.value, upstreamInput.value,
      { specSha256: sha(spec.bytes) });
    upstreamBytes = Buffer.from(JSON.stringify(upstreams, null, 2) + '\n');
    if (upstreamBytes.length > 1048576) throw new RangeError('Upstream config exceeds the SF30 1 MiB limit');
  }
  const responseFiles = [];
  if (serviceConfig?.routes.some(route => Object.hasOwn(route, 'responseFile'))) {
    const { readJsonResponseFile } = await import('../sf30-seller-sdk/response-file.mjs');
    for (const route of serviceConfig.routes) {
      if (!Object.hasOwn(route, 'responseFile')) continue;
      let snapshot;
      try {
        snapshot = await readJsonResponseFile(resolve(dirname(resolve(options.get('--service-bindings'))), route.responseFile));
      } catch (error) {
        throw new Error(`Route ${route.id} responseFile: ${error.message}`, { cause: error });
      }
      route.responseFile = 'responses/' + route.id + '.json';
      responseFiles.push({ routeId: route.id, file: route.responseFile, bytes: snapshot.source });
    }
  }
  const serviceBytes = serviceConfig ? Buffer.from(JSON.stringify(serviceConfig, null, 2) + '\n') : null;
  if (serviceBytes && serviceBytes.length > 1024 * 1024) throw new RangeError('Service config exceeds the SF30 1 MiB limit');
  const native = await readFile(new URL('../sf30-seller-discovery/index.mjs', import.meta.url));
  const adapter = await readFile(new URL('./importer.mjs', import.meta.url));
  const validator = await readFile(new URL('../../../stellar-forge/payment-auto-catalog/schema-validation.mjs', import.meta.url));
  const compatibility = await readFile(new URL('./schema-compat.mjs', import.meta.url));
  const manifest = { schema: 'stellar.open-api-seller-manifest.v1',
    specSha256: sha(spec.bytes), selectionsSha256: sha(config.bytes),
    sellerCompilerSha256: sha(native), validatorSha256: sha(validator), importerSha256: sha(adapter), offersSha256: sha(bytes),
    schemaCompatibilitySha256: sha(compatibility),
    operations: compiled.offers.map(({ method, path, sourcePointer, serverIndex }) => ({ method, path, sourcePointer, serverIndex })) };
  if (serviceBytes) {
    manifest.serviceBindingsSha256 = sha(bindings.bytes);
    manifest.serviceConfigSha256 = sha(serviceBytes);
    manifest.serviceAdapterSha256 = sha(await readFile(new URL('./service-config.mjs', import.meta.url)));
  }
  if (responseFiles.length) {
    manifest.responseFiles = responseFiles.map(({ routeId, file, bytes }) => ({ routeId, file, sha256: sha(bytes) }));
    manifest.responseFileLoaderSha256 = sha(await readFile(new URL('../sf30-seller-sdk/response-file.mjs', import.meta.url)));
  }
  if (upstreamBytes) {
    manifest.upstreamBindingsSha256 = sha(upstreamInput.bytes);
    manifest.upstreamConfigSha256 = sha(upstreamBytes);
    manifest.responseContractCompilerSha256 = sha(await readFile(new URL('./response-contracts.mjs', import.meta.url)));
    manifest.responseContractRuntimeSha256 = sha(await readFile(new URL('../sf30-seller-sdk/response-contract.mjs', import.meta.url)));
  }
  const output = resolve(options.get('--out'));
  await mkdir(output, { mode: 0o700 });
  if (responseFiles.length) {
    await mkdir(resolve(output, 'responses'), { mode: 0o700 });
    for (const { file, bytes } of responseFiles) await writeFile(resolve(output, file), bytes, { flag: 'wx', mode: 0o600 });
  }
  await writeFile(resolve(output, 'offers.json'), bytes, { flag: 'wx', mode: 0o600 });
  if (serviceBytes) await writeFile(resolve(output, 'seller-service.json'), serviceBytes, { flag: 'wx', mode: 0o600 });
  if (upstreamBytes) await writeFile(resolve(output, 'upstreams.json'), upstreamBytes, { flag: 'wx', mode: 0o600 });
  await writeFile(resolve(output, 'manifest.json'), JSON.stringify(manifest, null, 2) + '\n', { flag: 'wx', mode: 0o600 });
  if (report) process.stdout.write(JSON.stringify({ output, operations: compiled.offers.length, paymentsInitiated: 0 }) + '\n');
  return manifest;
}
if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href)
  run().catch(error => { process.stderr.write(error.message + '\n'); process.exitCode = 1; });

// MIT. Retained capture intake beside the original merchant source editor.
const make = (tag,text,cls) => {
  const node=document.createElement(tag);
  if(text!==undefined)node.textContent=text;
  if(cls)node.className=cls;
  return node;
};
const button = text => {const node=make('button',text);node.type='button';return node;};
const field = (title,type='text') => {
  const label=make('label',title), input=make('input');input.type=type;label.append(input);return {label,input};
};
function select(title,values) {
  const label=make('label',title), input=make('select');
  for(const [value,text] of values){const option=make('option',text);option.value=value;input.append(option);}
  label.append(input);return {label,input};
}
function sourceIdentity(text) {
  try {
    const value=JSON.parse(text)?.['x-starforge-har'];
    return value?.schema==='stellar.har-source.v1'?value:null;
  } catch {return null;}
}
function query(selected) {
  const result=new URLSearchParams({kind:selected.kind,id:selected.id});
  if(selected.revision)result.set('revision',selected.revision);
  return result.toString();
}

/** Keep commercial choices only for the same approved source or unchanged reviewed routes. */
export function mergeHarMerchantPlan({currentSource,currentPlan,prepared}) {
  const before=sourceIdentity(currentSource), after=sourceIdentity(prepared.specText);
  const same=Boolean(before && after && currentSource===prepared.specText);
  const previous=prepared.previous;
  const continuing=Boolean(before && previous &&
    before.sourceSha256===previous.previousSourceSha256 && before.reviewSha256===previous.previousReviewSha256);
  const carried=new Map((prepared.carry??[]).map(row=>[row.method+' '+row.path,row]));
  const saved=new Map((currentPlan.operations??[]).map(row=>[String(row.method).toUpperCase()+' '+row.path,row]));
  let preserved=0;
  const operations=prepared.operations.map(seed=>{
    const match=carried.get(seed.method+' '+seed.path);
    const old=saved.get(seed.method+' '+(continuing && match?match.previousPath:seed.path));
    if(!old || !same && !(continuing && match))return {...structuredClone(seed),amountAtomic:''};
    preserved++;
    const headers=new Map(Object.entries(old.headerEnv??{}).map(([name,value])=>[name.toLowerCase(),value]));
    for(const [name,value] of Object.entries(seed.headerEnv??{}))headers.set(name.toLowerCase(),value);
    return {...structuredClone(seed),...structuredClone(old),method:seed.method,path:seed.path,
      headerEnv:Object.fromEntries(headers),amountAtomic:old.amountAtomic??''};
  });
  const plan={...structuredClone(currentPlan),operations};
  if(plan.transports!==undefined) {
    const used=new Set(operations.map(row=>row.transport).filter(value=>value!==undefined));
    const profiles=Object.entries(plan.transports).filter(([alias])=>used.has(alias));
    if(profiles.length)plan.transports=Object.fromEntries(profiles);else delete plan.transports;
  }
  return {plan,preserved,needsPrice:operations.length-preserved};
}

export function createHarPanel({container,api,act,notice,token,onSource}) {
